package com.aoo.bcg.share;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.sun.net.httpserver.*;import java.io.IOException;import java.time.Duration;import java.util.*;
public final class InviteLinkHttpRoutes{private final JdbcInviteLinkRepository repo;private final InviteLinkSigner signer;private final InviteAccountAuthenticator auth;private final InviteRewardPort rewards;private final ObjectMapper json;public InviteLinkHttpRoutes(JdbcInviteLinkRepository r,InviteLinkSigner s,InviteAccountAuthenticator a,InviteRewardPort rewards,ObjectMapper j){repo=r;signer=s;auth=a;this.rewards=rewards;json=j;}
 public void mount(HttpServer s){s.createContext("/api/v2/invites",this::api);s.createContext("/i",this::landing);}private void api(HttpExchange e)throws IOException{try{String p=e.getRequestURI().getPath().substring("/api/v2/invites".length());long account=auth.authenticate(e.getRequestHeaders().getFirst("Authorization"));Object out;if(p.isEmpty()&&"POST".equals(e.getRequestMethod())){Map<String,Object>b=body(e);String t=signer.issue();out=repo.create(account,text(b,"kind"),number(b,"targetId"),Duration.ofSeconds(number(b,"ttlSeconds")),Math.toIntExact(number(b,"maxUses")),t,channel(e));}else if("/consume".equals(p)&&"POST".equals(e.getRequestMethod())){Map<String,Object>b=body(e);String code=signer.verify(String.valueOf(b.get("token")));var c=repo.consume(code,account,e.getRequestHeaders().getFirst("Idempotency-Key"),channel(e));if(!"GRANTED".equals(c.rewardState()))try{c=repo.rewarded(c.consumptionId(),rewards.grant(c));}catch(Exception dependency){throw new InviteLinkError(503,"INVITE_REWARD_PENDING","invite consumed; reward retry is pending");}out=Map.of("status","CONSUMED","rewardState",c.rewardState(),"target",c.target());}else if(p.matches("/\\d+/revoke")&&"POST".equals(e.getRequestMethod())){repo.revoke(account,Long.parseLong(p.split("/")[1]),channel(e));out=Map.of("status","REVOKED");}else throw new InviteLinkError(404,"INVITE_ROUTE_NOT_FOUND","invite route not found");reply(e,200,out);}catch(InviteLinkError x){error(e,x);}catch(Exception x){error(e,new InviteLinkError(400,"INVITE_INVALID_REQUEST","invite request is invalid"));}}
 private void landing(HttpExchange e)throws IOException{try{if(!"POST".equals(e.getRequestMethod()))throw new InviteLinkError(405,"INVITE_METHOD_NOT_ALLOWED","preview requires POST");String p=e.getRequestURI().getPath();if(!p.matches("/i/[A-Za-z0-9_-]{32}\\.[A-Za-z0-9_-]{22}"))throw notFound();String token=p.substring(3),code=signer.verify(token);Map<String,Object>out=new LinkedHashMap<>(repo.preview(code,channel(e),e.getRemoteAddress().getAddress().getHostAddress(),e.getRequestHeaders().getFirst("Referer")));out.put("token",token);reply(e,200,out);}catch(InviteLinkError x){error(e,x);}}
 private Map<String,Object>body(HttpExchange e)throws IOException{return json.readValue(e.getRequestBody(),new TypeReference<>(){});}private static String text(Map<String,Object>b,String k){Object v=b.get(k);if(!(v instanceof String s)||s.isBlank())throw bad(k);return s.toUpperCase();}private static long number(Map<String,Object>b,String k){Object v=b.get(k);if(!(v instanceof Number n))throw bad(k);return n.longValue();}private static InviteLinkError bad(String k){return new InviteLinkError(400,"INVITE_INVALID_REQUEST",k+" is required");}private static InviteLinkError notFound(){return new InviteLinkError(404,"INVITE_NOT_FOUND","invite link is unavailable");}private static String channel(HttpExchange e){String v=e.getRequestHeaders().getFirst("X-Invite-Source");return v==null||v.isBlank()?"direct":v;}private void error(HttpExchange e,InviteLinkError x)throws IOException{reply(e,x.status(),Map.of("code",x.code(),"message",x.getMessage()));}private void reply(HttpExchange e,int s,Object v)throws IOException{byte[]b=json.writeValueAsBytes(v);e.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");e.getResponseHeaders().set("Cache-Control","no-store");e.sendResponseHeaders(s,b.length);try(var o=e.getResponseBody()){o.write(b);}}}
